type LoadState =
    | { state: "loading" }
    | { state: "success"; data: string[] }
    | { state: "error"; message: string };

type LoadState = {
    state: string;
    data?: string[];
    message?: string;
};

function render(state: LoadState): string {
    switch (state.state) {
        case "loading":
            return "Loading...";

        case "success":
            return state.data.join(", ");

        case "error":
            return state.message;
    }
}
